// After an event scene: force the duel outcomes and switch effect 0 on
CMND_BTL_SET_EVPARAM(44070070);
suspend();
CMND_BTL_SET_FORCE_WIN(true, 0, 1, true);
CMND_BTL_SET_FORCE_WIN(true, 0, 0, true);
CMND_BTL_SET_MATCH_EFFECT(1, 0);

// Later, in the closing beat: switch everything back off
CMND_BTL_SET_MATCH_EFFECT(0, 0);
CMND_BTL_SET_MATCH_PHASE(1, 300);
CMND_BTL_SET_FORCE_WIN(false, 0, 1, true);
CMND_BTL_SET_FORCE_WIN(false, 0, 0, true);
